import{_ as a,C as s,o as n,c as r,a2 as t,E as i}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/characters-overview.webp",d="/guide/media/characters-notes.webp",c="/guide/media/characters-section.webp",l="/guide/media/characters-origin.webp",k=JSON.parse('{"title":"Characters","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters.md","filePath":"guide/characters.md","lastUpdated":1792685126000}'),g={name:"guide/characters.md"};function p(u,e,w,m,y,f){const o=s("Clip");return n(),r("div",null,[e[0]||(e[0]=t('<h1 id="characters" tabindex="-1">Characters <a class="header-anchor" href="#characters" aria-label="Permalink to &quot;Characters&quot;">​</a></h1><p>The Characters view gives each character of the story a sheet. It gathers what Leathercase already knows about them, where they are on stage, how their theme is tracking on the plot grid, who they share scenes with, the words they say, and sets it beside your own note on them. Your note is shown as you wrote it and is never written. What you add on the sheet goes into a note Leathercase keeps for the character in its own folder.</p><p><img src="'+h+'" alt="The character sheet of Nora Vidal: the cast on the left, her name and stage counts, the tabs, and the Overview with the strip of scenes, What Nora Vidal does, the five characters she shares scenes with, her relationships as her own note writes them, and her arc as its four stops; no theme on the grid is hers, so the strip has no gauge rows" width="808" height="1100" loading="lazy"></p><h2 id="opening-the-view" tabindex="-1">Opening the view <a class="header-anchor" href="#opening-the-view" aria-label="Permalink to &quot;Opening the view&quot;">​</a></h2><p>Open a story, then pick <strong>Characters</strong> under the story&#39;s name in the sidebar, or type &quot;Characters&quot; in the command palette (<code>Ctrl+K</code>, <code>Cmd+K</code> on macOS). It has no key of its own.</p><h2 id="who-is-in-the-cast" tabindex="-1">Who is in the cast <a class="header-anchor" href="#who-is-in-the-cast" aria-label="Permalink to &quot;Who is in the cast&quot;">​</a></h2><p>The cast is every character of the story that has a note: one of yours (a note typed as a character, or kept in a characters folder; see <a href="/guide/guide/how-a-story-is-read">How a story is read</a>), or one Leathercase keeps. Characters are listed most on stage first, then by name, each with the number of written scenes they are on stage in. A character only Leathercase keeps a note for is marked <strong>Leathercase</strong>.</p><p>Type in <strong>Filter the cast</strong> to narrow the list by name or by any other name the character goes by; case and accents do not matter. <code>Ctrl/Cmd+F</code> puts the caret there. When nothing matches, the page says &quot;No character matches.&quot;</p><p>With no character note at all, the view says &quot;No character has a note yet. Make one from the find field, character: a name, or give a character a note of your own.&quot; See <a href="/guide/guide/find">Find, open and make</a>.</p><p>The state line counts the cast, for example <code>6 characters with a note</code>.</p><h2 id="two-notes-per-character" tabindex="-1">Two notes per character <a class="header-anchor" href="#two-notes-per-character" aria-label="Permalink to &quot;Two notes per character&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Note</th><th>Where it lives</th><th>Who writes it</th></tr></thead><tbody><tr><td><strong>Your note</strong></td><td>Wherever you keep it, for example <code>The Lamp at Ferrol/Characters/Nora Vidal.md</code></td><td>You, in your own software. Leathercase only reads it.</td></tr><tr><td><strong>Leathercase&#39;s note</strong></td><td>The story&#39;s author data folder, <code>The Lamp at Ferrol/suite/Characters/Nora Vidal.md</code></td><td>You, from the sheet or in any editor; and the plot grid, between its <code>suite:grid</code> marks.</td></tr></tbody></table><p>When both exist, Leathercase&#39;s note sits beside yours as its counterpart: the Graph shows one Nora, not two. Leathercase&#39;s note is made the first time you ask for it (below), or by the plot grid when the character has an arc column there.</p><h2 id="the-sheet" tabindex="-1">The sheet <a class="header-anchor" href="#the-sheet" aria-label="Permalink to &quot;The sheet&quot;">​</a></h2><p>Pick a character to open their sheet. Its head shows the name, then on one line their other names (&quot;also Nora&quot;), their pronoun when Leathercase knows it, and how much of the story they are in: &quot;on stage in 18 of 20 written scenes&quot;, with &quot;19 through their eyes&quot; when they hold the point of view. <strong>Open the note</strong> opens your note in your software, and <strong>Open Leathercase&#39;s note</strong> opens Leathercase&#39;s.</p><p>Under the head is a row of tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Where they are in the story, how their theme tracks, what they do, who they share scenes with, their arc.</td></tr><tr><td><strong>Notes</strong></td><td>Your note as written, and Leathercase&#39;s note beside it.</td></tr><tr><td>One tab per section</td><td>Each section of Leathercase&#39;s note (Tropes, Motivation, Fears…), titled by its heading.</td></tr><tr><td><strong>Voice</strong></td><td>The words they say and never say, with a count of words.</td></tr><tr><td><strong>Origin</strong></td><td>Their past, before page one, with a count of events.</td></tr><tr><td><strong>From the plot grid</strong></td><td>The section the plot grid writes into Leathercase&#39;s note, when there is one.</td></tr></tbody></table><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><h3 id="through-the-story" tabindex="-1">Through the story <a class="header-anchor" href="#through-the-story" aria-label="Permalink to &quot;Through the story&quot;">​</a></h3><p>A strip with a column per scene of the grid, in order. The top row names each scene by number and title (past sixteen scenes, by number alone, the title on hover); click one to open it in the manuscript. The <strong>on stage</strong> row colours each scene: written and on stage, planned, or not in the scene, as the legend under the strip says.</p><p>The head lists the character&#39;s <strong>Gauges</strong>: their arc, and every theme or free column they own or share in a tug of war (see <a href="/guide/guide/plot-grid#belongs-to">Belongs to</a>), when it has a scale. <strong>Gauge Nora Vidal</strong> in the column menu draws them side by side on the grid.</p><p>When a theme on the plot grid belongs to the character (its heading ends in <code>· [[Nora Vidal]]</code>; see <a href="/guide/guide/plot-grid#belongs-to">Belongs to</a>), the strip&#39;s head names it, &quot;Theme: …&quot;, with its scale, and three more rows follow:</p><ul><li><strong>gauge</strong>: a bar per scene for its charge, from −2 to +2 on a five-word scale, and a dashed line for the running total.</li><li><strong>word</strong>: the word on the scale that scene was given, or the signed charge when there are many scenes.</li><li><strong>total</strong>: the running total after that scene.</li></ul><p>Without such a theme, the strip says &quot;No theme on the plot grid belongs to Nora Vidal. A theme heading ending in · [[Nora Vidal]] makes it theirs.&quot; With a theme but no scale: &quot;The theme has no scale yet: give it one on the plot grid to read its gauge.&quot; <strong>open the plot grid</strong> goes there.</p><h3 id="what-they-do" tabindex="-1">What they do <a class="header-anchor" href="#what-they-do" aria-label="Permalink to &quot;What they do&quot;">​</a></h3><p><strong>What Nora Vidal does</strong> lists the scenes one by one, &quot;from their arc on the grid, else the scene&#39;s summary&quot;: what the arc&#39;s stops say at that scene, or the scene&#39;s summary when the character is on stage and the arc says nothing, with the places of the scene. A scene they are not in reads &quot;not in this scene&quot;. Runs of quiet scenes fold into one line: &quot;not in these 4 scenes&quot;, or &quot;on stage in all 3, with nothing on the grid for them yet&quot;. The scene to write next is marked <strong>next to write</strong>. Each line&#39;s scene opens in the manuscript.</p><h3 id="for-the-arc" tabindex="-1">For the arc <a class="header-anchor" href="#for-the-arc" aria-label="Permalink to &quot;For the arc&quot;">​</a></h3><p>Plain readings of the theme&#39;s gauge, &quot;counted from the grid&quot;, each with the numbers under it:</p><ul><li>&quot;The running total stays above zero at every stop: the theme never turns.&quot; (or below zero)</li><li>&quot;To end above zero, the stops need to rise by 3 between them.&quot;</li><li>&quot;The running total changes sign twice.&quot;</li><li>&quot;The biggest swing is 5 to 8: doubt to light.&quot;</li><li>&quot;The theme has no scene with a word on its scale yet.&quot;</li><li>&quot;The grid has no want, lie, turn or truth stops for this character yet.&quot;</li></ul><p>Readings to look at carry an amber dot. Without a theme of theirs: &quot;Readings come from a theme that belongs to the character, on the plot grid.&quot;</p><h3 id="shares-scenes-with-relationships-arc" tabindex="-1">Shares scenes with, Relationships, Arc <a class="header-anchor" href="#shares-scenes-with-relationships-arc" aria-label="Permalink to &quot;Shares scenes with, Relationships, Arc&quot;">​</a></h3><ul><li><strong>Shares scenes with</strong> lists the other characters on stage with them, up to five, with the number of scenes together and where; click a name to open that sheet. Only characters are listed: places and events are the <a href="/guide/guide/graph">Graph</a>&#39;s to show. With nobody: &quot;Shares no scene yet.&quot;</li><li><strong>Relationships</strong> lists the relationships written in notes or drawn on the old story map, with their labels; one from the old map says <strong>drawn on the map</strong>. Ties you draw in the <a href="/guide/guide/graph">Graph</a> are kept there. When the character&#39;s own note names someone, that line is shown, saying who the other is to them. A line written only in the other character&#39;s note says what this character is to them: Bastian Kell&#39;s note does not name Nora, so on his sheet her line, from her note, reads <strong>Nora Vidal · in their note: the man who wants the point</strong>. Click a character to open their sheet, anything else to open the <a href="/guide/guide/graph">Graph</a>.</li><li><strong>Arc</strong>, &quot;From the plot grid&quot;: the arc&#39;s summary as the grid wrote it, with <strong>full text</strong> to open the <strong>From the plot grid</strong> tab. When the grid wrote no paragraph for the arc, its stops are listed instead, one per line with the stop&#39;s role. Without an arc: &quot;No arc on the grid.&quot; or &quot;The arc has no scenes on the grid yet.&quot;</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Two panels side by side.</p><p><strong>Your note</strong> shows your note as you wrote it, its path above, drawn as an outline: headings, lists, tables, checkboxes, paragraphs. Bold text keeps a thin amber line under it, as a thing you marked. A <code>[[link]]</code> to another character opens their sheet. A web link with notes under it is drawn as a card you can fold, and a line of web links as chips. Nothing is reworded, and nothing here edits your note. A character only Leathercase keeps says &quot;Only Leathercase keeps a note for this character.&quot;</p><p><strong>Leathercase&#39;s note</strong> shows its path and its text in a field you can edit. It is saved when you leave the field or press <code>Ctrl/Cmd+Enter</code>. The line under it says whether it is &quot;Leathercase&#39;s note beside yours, in the author data folder; the plot grid writes its section there&quot; or &quot;made by Leathercase for this story, in its author data folder&quot;.</p><p>When Leathercase keeps no note yet, the panel says &quot;Leathercase keeps no note for this character yet.&quot; with <strong>Make Leathercase&#39;s note</strong>, which makes it with the home&#39;s character sections, empty.</p><p>When Leathercase&#39;s note lacks some of the home&#39;s character sections, <strong>Add 3 sections</strong> (the count is how many are missing) adds them, empty, after your text. They are written at the level the note keeps its sections at (<code>##</code> in a note whose sections are <code>##</code>, <code>###</code> in a note with none yet), so each becomes a tab beside the others. It never adds a section twice and never touches a heading you wrote.</p><p><img src="'+d+`" alt="The Notes tab: Nora Vidal&#39;s own note as an outline on the left, Leathercase&#39;s note in an editable field on the right" width="863" height="1018" loading="lazy"></p><h2 id="character-sections" tabindex="-1">Character sections <a class="header-anchor" href="#character-sections" aria-label="Permalink to &quot;Character sections&quot;">​</a></h2><p>The sections Leathercase adds to a character&#39;s note are the home&#39;s own list, the same for every story in it. A new home starts with Tropes, Motivation, Emotional wounds, Emotion amplifiers, Fears, Positive traits and Negative traits.</p><p>To change the list, open the story&#39;s settings (<strong>Story settings</strong> in the story&#39;s menu or the palette; see <a href="/guide/guide/story-settings">Story settings</a>) and find <strong>Character sections</strong>: one section per line, &quot;for every story of the home&quot;. <strong>Save the sections</strong> writes them. The list is kept in <code>suite/CharacterSections.md</code> at the root of your writing home, a plain list you can also edit by hand:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Character sections</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Tropes</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Motivation</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Fears</span></span></code></pre></div><p>Changing the list adds nothing by itself. Use <strong>Add … sections</strong> on a character&#39;s Notes tab to bring their note up to date.</p><h2 id="section-tabs" tabindex="-1">Section tabs <a class="header-anchor" href="#section-tabs" aria-label="Permalink to &quot;Section tabs&quot;">​</a></h2><p>Each section of Leathercase&#39;s note gets a tab, in the note&#39;s order. A section is a heading at the note&#39;s top level: <code>###</code> in a note filled by <strong>Add … sections</strong>, <code>##</code> in one written that way by hand. The Origin section has its own tab. A section tab shows:</p><ul><li>An index of the section&#39;s sub-headings, with how many items each holds; click one to scroll to it.</li><li>The section drawn as written, marked &quot;from Leathercase&#39;s note, as written&quot;. An empty section says &quot;Nothing written in this section yet.&quot;</li><li><strong>Edit here</strong> turns the section into a field. <strong>Save the section</strong> writes only that section back; the rest of the note stays as it was. <strong>Cancel</strong> leaves it. <strong>Open Leathercase&#39;s note</strong> opens the whole note in your software.</li><li>Beside it, <strong>What you marked</strong>: <strong>Questions you bolded</strong> (each with the sub-heading it sits under), <strong>Linked here</strong> (the notes the section links to, with a count; a name with no note is marked <strong>no note</strong>, and a character&#39;s name opens their sheet), and how many lines still end in a question.</li></ul><p><img src="`+c+'" alt="A section tab, Fears: the sub-headings index, the section as written, and the bolded questions beside it" width="903" height="515" loading="lazy"></p><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h2><p>The Voice tab keeps the words a character says and the words they never say. The accents lens in the <a href="/guide/guide/lenses">manuscript</a> marks them, and counts a &quot;never&quot; word said in their speech as a slip.</p><p>Two lists, as pills:</p><ul><li><strong>Says</strong>, &quot;words and phrases that are theirs&quot;, with the number of words and marks.</li><li><strong>Never says</strong>, &quot;shown as slips when said&quot;, with the number of words and slips.</li></ul><p>Each pill shows its count in certain speech; hover for the count in lines only guessed too. To add a word, type it in <strong>A word or a short phrase</strong> and press <code>Enter</code> or click <strong>Add</strong>. Leaving the field keeps it too; <code>Esc</code> drops it. Words are kept lower case, with straight apostrophes.</p><p>A word can be in one list only. Typing a word that is in the other list says so: &quot;“aye” is in Says. One list per word.&quot; with <strong>Move it here</strong>.</p><p>Click a pill for its menu: <strong>Move to Never says</strong> (or Says), <strong>Show its 3 marks in the manuscript</strong>, and <strong>Remove</strong>; the <code>×</code> on a pill removes it too. Each change is announced, such as &quot;“aye” moved to Never says. Its 2 marks in certain speech now count as slips.&quot;, with <strong>undo</strong>; <strong>undo the last change</strong> steps back further.</p><p>Words that come from the character&#39;s own note (<code>accent:</code> and <code>accent-never:</code> in its front matter) show dashed with a lock. Their menu offers <strong>Change it in Nora Vidal.md</strong> and the marks; change them in your note.</p><p>Words you add here are kept in <code>suite/Accents.md</code> in the story&#39;s folder, never in your note.</p>',57)),i(o,{name:"characters-voice",caption:"Typing aye into Says and leaving the field: the word is kept; then moving it to Never says from its pill's menu"}),e[1]||(e[1]=t(`<h3 id="in-the-manuscript" tabindex="-1">In the manuscript <a class="header-anchor" href="#in-the-manuscript" aria-label="Permalink to &quot;In the manuscript&quot;">​</a></h3><p>Beside the lists:</p><ul><li>Three counts: <strong>marks in certain speech</strong>, <strong>more in guessed lines</strong>, and <strong>slips</strong> (in amber when there are any).</li><li>How many lines are theirs: &quot;42 lines are theirs: 30 certain, 12 guessed by turn-taking&quot;.</li><li>Each slip, &quot;slip: aye in The hall&quot;, with <strong>show it</strong>.</li><li><strong>Open the accents lens</strong> opens the manuscript with the lens on.</li></ul><p><strong>Lines only guessed</strong> lists the scenes where only turn-taking gives lines to the character, with <strong>go to the line</strong>. &quot;Only turn-taking gives these lines to Nora Vidal, so the accents lens dots their words and never counts a slip. A tag, a name, or a <code>%% Nora Vidal %%</code> pin before the line makes it certain.&quot; When all are certain: &quot;Every line of theirs is certain.&quot;</p><h2 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;Origin&quot;">​</a></h2><p>The Origin tab, <strong>Before page one</strong>, plans the character&#39;s past as a timeline by age. It is kept as the Origin section of Leathercase&#39;s note, at the level the note keeps its sections at (<code>## Origin</code> with <code>###</code> events in a note whose sections are <code>##</code>, one level lower in a note whose sections are <code>###</code>), yours to write here or in your editor:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Origin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 9 · Her father takes her up the tower</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">with: Tomás Vidal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">left: Fear of the dark</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shows: [[01 The Night the Lamp Went Out#The tower]]</span></span></code></pre></div><p>To add an event, type an <strong>Age</strong> (optional: &quot;9&quot;, &quot;20s&quot;, &quot;30-34&quot;) and <strong>What happened</strong>, then press <code>Enter</code>, click <strong>Add</strong>, or leave the row. <code>Esc</code> clears it. Events are ordered by age. If the character has no Leathercase note yet, adding the first event makes it.</p><p>On each event&#39;s card:</p><ul><li><strong>who was there</strong>: a line written in place, kept on <code>Enter</code> or when you leave it.</li><li>Chips for what the event left the character with; the <code>×</code> takes one off.</li><li><strong>shows in …</strong> links to scenes where the event shows; click to open the scene, <code>×</code> to take it off.</li><li><strong>link</strong> opens a menu: the entries of Leathercase&#39;s note&#39;s link lists (lines that are each one markdown link, such as <code>[Fear of the dark](https://…)</code>, without a list marker), grouped by the heading they sit under (wounds, fears, motivations), and <strong>Shows in</strong>, the scenes the character is on stage in. Picking one adds it.</li><li>The <code>×</code> at the card&#39;s corner removes the event.</li></ul><p>Beside the timeline:</p><ul><li><strong>Not traced to an event</strong> lists the link-list entries no event has left yet, by group, with a count such as &quot;2 of 5 linked to an event&quot;. With no link lists in the note: &quot;Leathercase&#39;s note lists nothing to link yet: a list of links under a heading (wounds, fears, motivations) shows here.&quot;</li><li><strong>People from before</strong> lists the names in the events&#39; &quot;who was there&quot; lines that are not in the cast, with how many events each is in. &quot;Everyone named in an event is in the cast.&quot; when there are none.</li></ul><p>The footer says where it is kept: &quot;Kept as the Origin section of suite/Characters/Nora Vidal.md, Leathercase&#39;s note on Nora Vidal: yours to write here or in your editor. Your own note is never written.&quot;</p><p><img src="`+l+'" alt="The Origin tab: three events by age with who was there, their chips and shows in links, the add row, and Not traced to an event and People from before beside" width="884" height="705" loading="lazy"></p><h2 id="from-the-plot-grid" tabindex="-1">From the plot grid <a class="header-anchor" href="#from-the-plot-grid" aria-label="Permalink to &quot;From the plot grid&quot;">​</a></h2><p>When the character has an arc column on the plot grid, the grid writes a section into their Leathercase note: the arc&#39;s want, lie, turn and truth, and each stop with its scene. This tab shows it, dashed, with &quot;Kept by the plot grid in StoryThreads.md; change it there.&quot; and <strong>open the plot grid</strong>. Edit the arc on the <a href="/guide/guide/plot-grid">plot grid</a>, not in this section.</p><h2 id="what-an-agent-wrote-on-the-sheet" tabindex="-1">What an agent wrote on the sheet <a class="header-anchor" href="#what-an-agent-wrote-on-the-sheet" aria-label="Permalink to &quot;What an agent wrote on the sheet&quot;">​</a></h2><p>An agent you connected with <strong>Lay out</strong> can propose what a section of a character&#39;s sheet says (Wants, Fears), from your prose, and events of their past for Origin. Its pronoun and other names it may propose too; those go to the story&#39;s settings. Accepted, a section and an event are drawn on the layer&#39;s grey, and their hover names the agent, until you change them; editing a section never shows you Leathercase&#39;s mark. The facts you accepted about the story that name the character are listed under <strong>Facts</strong> on the Overview, with the scene and the sentence each rests on; you edit them in <code>Facts.md</code>.</p><h2 id="what-the-view-writes" tabindex="-1">What the view writes <a class="header-anchor" href="#what-the-view-writes" aria-label="Permalink to &quot;What the view writes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>When</th></tr></thead><tbody><tr><td><code>suite/Characters/</code> <code>Name.md</code> in the story&#39;s folder</td><td><strong>Make Leathercase&#39;s note</strong>, <strong>Add … sections</strong>, editing Leathercase&#39;s note or a section, adding an Origin event</td></tr><tr><td><code>suite/Accents.md</code> in the story&#39;s folder</td><td>Adding, moving or removing a word on the Voice tab</td></tr><tr><td><code>suite/CharacterSections.md</code> at the root of the home</td><td>Saving the character sections in Story settings</td></tr></tbody></table><p>Your own notes and chapters are never written. See <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/plot-grid">Plot grid</a>, for arcs, themes and the gauge</li><li><a href="/guide/guide/graph">Graph</a>, for ties, roles and other names</li><li><a href="/guide/guide/lenses">Lenses and style checks</a>, for the accents lens</li><li><a href="/guide/guide/story-settings">Story settings</a>, for the character sections</li><li><a href="/guide/reference/front-matter">Front matter</a>, for <code>accent:</code> and <code>accent-never:</code></li></ul>',23))])}const q=a(g,[["render",p]]);export{k as __pageData,q as default};
